void open_url(const std::string &url) {
    std::string executable;

#if defined(_WIN32) || defined(_WIN64)
    executable = "start \"";
#elif defined(__linux__)
    executable = "xdg-open";
#elif defined(__APPLE__)
    executable = "open";
#elif defined(__ANDROID__)
    executable = "am start -a android.intent.action.VIEW -d";
#endif

    // Sanitize the URL to prevent OS command injection
    std::string sanitized_url = url;
    for (char &c : sanitized_url) {
        if (c == '"' || c == '&' || c == ';' || c == '`' || c == '\' || c == '$' || c == '(' || c == ')' || c == '<' || c == '>' || c == '|' || c == '^' || c == '*') {
            c = '_';
        }
    }

    const std::string command = executable + " \"" + sanitized_url + "\"";

    const int exitcode = std::system(command.c_str());
    if (exitcode != 0) {
        // debugmsg("Failed to open URL: %s\nAttemped command was: %s", url, command);
        // Replace debugmsg with your debugging/logging function
    }
}

